namespace sct::ui {
class FreehandAccess {
    using Check=std::function<void(bool,const char*)>;
    static bool Wait(EditorFrame* page){const auto end=std::chrono::steady_clock::now()+std::chrono::seconds(5);do{services::PumpNativeTestMessages();if(!page->WorkingForBuild())return true;Sleep(2);}while(std::chrono::steady_clock::now()<end);return false;}
    static void Mouse(EditorFrame* page,UINT message,CPoint point){services::NeutralTestKeys();const auto p=page->ScreenRect({point.x,point.y,point.x,point.y}).TopLeft();page->SendMessage(message,message==WM_LBUTTONUP?0:MK_LBUTTON,MAKELPARAM(p.x,p.y));}
    static void Drag(EditorFrame* page,CPoint start,CPoint end){Mouse(page,WM_LBUTTONDOWN,start);Mouse(page,WM_MOUSEMOVE,end);Mouse(page,WM_LBUTTONUP,end);}
    static void Escape(EditorFrame* page){services::NeutralTestKeys();MSG message{};message.hwnd=page->m_hWnd;message.message=WM_KEYDOWN;message.wParam=VK_ESCAPE;page->PreTranslateMessage(&message);}
    static core::Image Paint(EditorFrame* page){
        CRect r;page->GetClientRect(r);CClientDC screen(page);CDC dc;dc.CreateCompatibleDC(&screen);BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=r.Width();info.bmiHeader.biHeight=-r.Height();info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* pixels=nullptr;auto bitmap=CreateDIBSection(screen,&info,DIB_RGB_COLORS,&pixels,nullptr,0);if(!bitmap)return {};auto old=::SelectObject(dc,bitmap);dc.FillSolidRect(r,RGB(249,250,251));page->PaintContent(dc);GdiFlush();core::Image image;image.Create(r.Width(),r.Height());memcpy(image.pixels.data(),pixels,image.pixels.size());for(size_t i=3;i<image.pixels.size();i+=4)image.pixels[i]=255;::SelectObject(dc,old);::DeleteObject(bitmap);return image;
    }
    static size_t Green(const core::Image& image){size_t count=0;for(size_t i=0;i+3<image.pixels.size();i+=4)if(image.pixels[i]==80&&image.pixels[i+1]==255&&image.pixels[i+2]==20)++count;return count;}
    static size_t Frames(const core::Image& image){size_t count=Green(image);for(size_t i=0;i+3<image.pixels.size();i+=4)if(image.pixels[i]==((selection::Outline>>16)&255)&&image.pixels[i+1]==((selection::Outline>>8)&255)&&image.pixels[i+2]==(selection::Outline&255))++count;return count;}
    static void HollowControls(EditorFrame* page,Check check){
        CClientDC screen(page);CDC dc;dc.CreateCompatibleDC(&screen);BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=80;info.bmiHeader.biHeight=-80;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* pixels=nullptr;auto bitmap=CreateDIBSection(screen,&info,DIB_RGB_COLORS,&pixels,nullptr,0);check(bitmap!=nullptr,"selection-style test bitmap allocated");if(!bitmap)return;auto old=::SelectObject(dc,bitmap);
        for(const auto background:{RGB(255,255,255),RGB(24,26,30),RGB(50,130,190)}){
            dc.FillSolidRect(0,0,80,80,background);dc.SetBkMode(OPAQUE);dc.SetBkColor(RGB(220,0,220));
            selection::Box(dc,CRect(8,8,72,72));selection::Handle(dc,{28,40},5);selection::Handle(dc,{52,40},5,true);GdiFlush();
            auto pixel=[&](int x,int y){const auto* p=static_cast<BYTE*>(pixels)+(y*80+x)*4;return RGB(p[2],p[1],p[0]);};
            bool gap=true;for(int x=12;x<68;++x)if(pixel(x,8)!=background&&pixel(x,8)!=selection::Outline)gap=false;
            check(pixel(28,40)==background&&pixel(52,40)==background,"square and round control centers preserve white/dark/colored pixels without solid fill");
            check(pixel(23,40)==selection::Outline&&pixel(47,40)==selection::Outline&&gap,"one-pixel pale guides and hollow controls remain visible without opaque dotted gaps");
            check(dc.GetBkMode()==OPAQUE&&dc.GetBkColor()==RGB(220,0,220),"selection styling restores the caller drawing state");
        }
        ::SelectObject(dc,old);::DeleteObject(bitmap);
    }
    static void Evidence(EditorFrame* page,const std::filesystem::path& path,Check check){CString error;std::vector<BYTE> bytes;check(services::EncodeImage(Paint(page),L"png",100,bytes,error)&&services::WriteBytes(path.c_str(),bytes,error),"own freehand paint evidence saved without capturing the desktop");}
public:static void Run(Check check,std::ofstream& log,const std::filesystem::path& dir){
        const auto foreground=GetForegroundWindow();const DWORD clipboard=GetClipboardSequenceNumber();core::Image source;source.Create(300,180);const auto original=source.pixels;
        auto* owner=new CFrameWnd;owner->Create(nullptr,L"SCT hidden freehand fixture",WS_OVERLAPPEDWINDOW,CRect(0,0,1600,1200));owner->ModifyStyleEx(0,WS_EX_NOACTIVATE|WS_EX_TOOLWINDOW);owner->EnableWindow(FALSE);auto* page=new EditorFrame(core::Document(source).State(),L"",owner);page->EnableWindow(FALSE);page->text_.EnableWindow(FALSE);page->SetWindowPos(nullptr,0,0,1500,1100,SWP_NOZORDER|SWP_NOACTIVATE);Wait(page);
        auto reset=[&]{Wait(page);page->selected_=-1;page->pixelSelection_.SetRectEmpty();page->document_.Reset(core::Document(source).State());page->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::Pen));page->style_.color=RGB(220,20,30);page->style_.alpha=255;page->Changed();Wait(page);page->dirty_=false;page->ZoomTo(1);};
        auto cleanup=[&]{layoutTestDpi=0;if(page->GetCapture()==page)::ReleaseCapture();Wait(page);page->dirty_=false;page->DestroyWindow();owner->DestroyWindow();services::PumpNativeTestMessages();};
        try{
            const std::vector<CPoint> path={{20,40},{40,20},{80,80},{120,60},{160,120},{220,100}};
            for(int dpi:{96,120})for(double zoom:{.5,1.,2.}){
                reset();layoutTestDpi=dpi;page->Layout();page->ZoomTo(zoom);page->offsetX_=page->offsetY_=0;page->ClampViewport();const auto revision=page->revision_;const auto base=page->document_.State().base;
                Mouse(page,WM_LBUTTONDOWN,path.front());for(size_t i=1;i<path.size();++i)Mouse(page,WM_MOUSEMOVE,path[i]);check(Wait(page)&&page->dragging_&&page->document_.State().objects.empty()&&page->revision_==revision&&page->draft_.points.size()>=path.size(),"native pen moves retain the full pointer path without committing while the button is held");
                bool retained=true;for(const auto p:path)retained=retained&&std::any_of(page->draft_.points.begin(),page->draft_.points.end(),[&](POINT q){return q.x==p.x&&q.y==p.y;});check(retained&&page->image_.Row(20)[40*4+2]>180&&page->image_.Row(20)[40*4]<100,"live pen preview follows intermediate bends rather than the bounding rectangle or endpoint line");check(Frames(Paint(page))==0,"drawing-time preview has no object frame at 50/100/200-percent zoom and 100/125-percent DPI");if(dpi==96&&zoom==1)Evidence(page,dir/L"pen-live-no-frame.png",check);
                Mouse(page,WM_LBUTTONUP,path.back());check(Wait(page)&&page->document_.State().objects.size()==1&&page->selected_<0&&page->style_.tool==core::Tool::Pen&&page->revision_==revision+1&&page->document_.State().base==base,"pen release commits one editable stroke while keeping the pen active and deselected");check(Frames(Paint(page))==0,"a completed pen stroke has no automatic editing handles");
                page->OnAction(Undo);check(Wait(page)&&page->document_.State().objects.empty(),"one undo removes one complete freehand gesture");page->OnAction(Redo);check(Wait(page)&&page->document_.State().objects.size()==1&&page->document_.State().objects[0].points.size()>=path.size(),"redo restores the complete editable pointer path");
            }
            layoutTestDpi=0;page->Layout();page->ZoomTo(1);const auto first=page->document_.State().objects[0];page->SendMessage(WM_COMMAND,PaletteFirst+8);Mouse(page,WM_LBUTTONDOWN,{40,20});Mouse(page,WM_MOUSEMOVE,{40,130});Mouse(page,WM_MOUSEMOVE,{150,130});Mouse(page,WM_LBUTTONUP,{220,20});
            check(Wait(page)&&page->document_.State().objects.size()==2&&page->selected_<0&&page->style_.tool==core::Tool::Pen,"a second overlapping drag starts another pen stroke instead of moving the previous one");check(page->document_.State().objects[0].color==first.color&&page->document_.State().objects[0].points.front().x==first.points.front().x&&page->document_.State().objects[1].color==QuickColors()[8],"changing pen color between strokes preserves the first stroke and applies to the next one");Evidence(page,dir/L"pen-consecutive-red-blue.png",check);
            page->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::Rectangle));Mouse(page,WM_LBUTTONDOWN,{20,40});Mouse(page,WM_LBUTTONUP,{20,40});check(Wait(page)&&page->selected_==0&&page->style_.tool==core::Tool::Select&&Frames(Paint(page))>0&&Green(Paint(page))==0,"intentional direct click still selects an existing pen object with pale editing controls");
            Drag(page,{20,40},{30,50});check(Wait(page)&&page->document_.State().objects[0].points.front().x==30&&page->document_.State().objects[0].points.front().y==50,"an intentionally selected pen stroke remains movable as an editable object");page->OnAction(Undo);check(Wait(page)&&page->document_.State().objects[0].points.front().x==20,"one undo restores a deliberately moved pen stroke");
            page->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::Pen));const auto count=page->document_.State().objects.size();const auto revision=page->revision_;Mouse(page,WM_LBUTTONDOWN,{200,150});Mouse(page,WM_MOUSEMOVE,{260,150});Escape(page);Mouse(page,WM_LBUTTONUP,{260,150});check(Wait(page)&&page->document_.State().objects.size()==count&&page->revision_==revision&&Frames(Paint(page))==0,"Escape cancels a pen preview without adding an object or undo revision");
            Mouse(page,WM_LBUTTONDOWN,{200,160});Mouse(page,WM_MOUSEMOVE,{260,160});if(page->GetCapture()==page)::ReleaseCapture();Mouse(page,WM_LBUTTONUP,{260,160});check(Wait(page)&&page->document_.State().objects.size()==count&&page->revision_==revision,"capture loss cancels a pen stroke without committing stray pixels");
            page->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::Rectangle));Drag(page,{230,40},{280,100});check(Wait(page)&&page->document_.State().objects.back().tool==core::Tool::Rectangle&&page->selected_>=0&&Frames(Paint(page))>0&&Green(Paint(page))==0,"shape drawing retains post-draw selection with pale rather than green controls");Evidence(page,dir/L"selection-pale-frame.png",check);
            page->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::Highlight));Drag(page,{230,120},{280,150});const CRect highlight(230,120,280,150);check(Wait(page)&&page->document_.State().objects.back().tool==core::Tool::Highlight&&EqualRect(&page->document_.State().objects.back().rect,&highlight),"user-confirmed highlighter remains a rectangular region instead of a freehand stroke");
            HollowControls(page,check);
            for(const auto tool:{core::Tool::Arrow,core::Tool::CurvedArrow}){
                reset();page->OnToolCommand(EditorToolFirst+static_cast<UINT>(tool));Mouse(page,WM_LBUTTONDOWN,{30,40});check(page->dragging_,"native arrow press starts a drawing gesture");Mouse(page,WM_MOUSEMOVE,{220,140});Mouse(page,WM_LBUTTONUP,{220,140});const bool ready=Wait(page);log<<"ARROW fixture tool="<<static_cast<int>(tool)<<" actual="<<static_cast<int>(page->style_.tool)<<" count="<<page->document_.State().objects.size()<<" selected="<<page->selected_<<" ready="<<ready<<" dragging="<<page->dragging_<<" canvasHandle="<<page->canvasHandle_<<"\n";check(ready&&page->selected_>=0&&Frames(Paint(page))>0&&Green(Paint(page))==0,"straight and curved arrows show pale editable nodes instead of bright green blocks");if(page->document_.State().objects.empty())continue;
                const auto before=core::ArrowNodes(page->document_.State().objects.back());const size_t index=tool==core::Tool::Arrow?0:1;const auto screen=page->ScreenRect({before[index].x,before[index].y,before[index].x,before[index].y}).TopLeft();check(page->Handle(screen)==100+static_cast<int>(index),"hollow arrow nodes retain their original hit target");
                Drag(page,{before[index].x,before[index].y},{90,20});Wait(page);const auto after=core::ArrowNodes(page->document_.State().objects.back());check(after.size()==before.size()&&after[index].x==90&&after[index].y==20&&after.back().x==before.back().x&&after.back().y==before.back().y,"native dragging still edits an individual endpoint or curve control without moving the head");Evidence(page,dir/(tool==core::Tool::Arrow?L"selection-pale-arrow.png":L"selection-pale-curve.png"),check);
            }
            reset();page->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::PixelSelect));Drag(page,{30,30},{180,120});check(Wait(page)&&!page->pixelSelection_.IsRectEmpty()&&Frames(Paint(page))>0&&Green(Paint(page))==0,"pixel selection retains its necessary range with the shared pale outline");
            check(source.pixels==original&&page->document_.State().base->pixels==original,"freehand editing and selection overlays never mutate the source image buffer");DWORD fg=0,clip=0;GetWindowThreadProcessId(GetForegroundWindow(),&fg);GetWindowThreadProcessId(GetClipboardOwner(),&clip);check(GetForegroundWindow()==foreground||fg!=GetCurrentProcessId(),"hidden freehand fixture never takes the user's foreground focus");check(GetClipboardSequenceNumber()==clipboard||clip!=GetCurrentProcessId(),"freehand tests never publish clipboard contents or block user copying");log<<"FREEHAND only: native pen input/preview/paint and affected selection visuals/arrow nodes; no capture/hotkeys/dialogs/recording/clipboard publication/full regression\n";cleanup();
        }catch(...){cleanup();throw;}
    }
};
}
namespace sct::services {void FreehandChecks(const std::function<void(bool,const char*)>& check,std::ofstream& log,const std::filesystem::path& dir){ui::FreehandAccess::Run(check,log,dir);}}
